package com.kuaixietech.aftersalesfunds;
import com.fasterxml.jackson.databind.*;
import com.kuaixietech.service.trading.support.IntentPricing;
import java.math.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
/** A proof of unspent original escrow, not an inference from case status or a wallet top-up. */
@Component
public class EscrowFundsProof {
 public static final String LEDGER_KIND="as_goods_refund";
 public static final class Blocked extends IllegalStateException {public Blocked(String code){super(code);}}
 public record Proof(Map<String,Object> order,Map<String,Object> reservation,Map<String,Object> buyerDeposit,List<Map<String,Object>> executions,BigDecimal goods,BigDecimal fee,BigDecimal shipping,BigDecimal refunded,BigDecimal held,String buyer,String vendor) {public BigDecimal remainingGoods(){return goods.subtract(refunded);}}
 private final JdbcTemplate db;private final ObjectMapper json;
 public EscrowFundsProof(JdbcTemplate db,ObjectMapper json){this.db=db;this.json=json;}
 private Blocked blocked(String code){return new Blocked(code);}
 static BigDecimal amount(Object value){if(value==null)throw new Blocked("AS_ESCROW_AMOUNT_MISSING");try{return new BigDecimal(value.toString()).setScale(2,RoundingMode.UNNECESSARY);}catch(Exception e){throw new Blocked("AS_ESCROW_AMOUNT_INVALID");}}
 static String text(Map<String,Object> row,String field){return Objects.toString(row.get(field),null);}
 static boolean truth(Object value){return Boolean.TRUE.equals(value)||"1".equals(Objects.toString(value));}
 private Map<String,Object> one(String sql,Object...args){var rows=db.queryForList(sql,args);if(rows.size()!=1)throw blocked("AS_ESCROW_SOURCE_NOT_UNIQUE");return rows.getFirst();}
 private JsonNode object(Object raw){try{JsonNode value=json.readTree(Objects.toString(raw,""));if(value==null||!value.isObject())throw new IllegalArgumentException();return value;}catch(Exception e){throw blocked("AS_ESCROW_SNAPSHOT_INVALID");}}
 private BigDecimal decimal(JsonNode object,String key){if(!object.hasNonNull(key))throw blocked("AS_ESCROW_SNAPSHOT_INCOMPLETE");return amount(object.get(key).asText());}
 public Proof prove(String orderId,Map<String,Object> order,boolean lock){String suffix=lock?" FOR UPDATE":"";if(!"product_order".equals(order.get("source"))||!Set.of("purchased","shipped").contains(order.get("status"))||order.get("settled_at")!=null||!"frozen".equals(order.get("buyer_deposit_status")))throw blocked("AS_ESCROW_ORDER_NOT_UNSETTLED");String buyer=text(order,"buyer_id"),vendor=text(order,"vendor_id");if(buyer==null||vendor==null||buyer.equals(vendor)||!"frozen".equals(order.get("vendor_deposit_status")))throw blocked("AS_ESCROW_PARTIES_OR_DEPOSITS_UNPROVEN");
  if(amount(Objects.requireNonNullElse(order.get("insurance_premium"),BigDecimal.ZERO)).signum()!=0)throw blocked("AS_ESCROW_HISTORICAL_INSURANCE_REQUIRES_RECONCILIATION");String tax=text(order,"tax_refund_plan");if(tax!=null&&!tax.equals("vendor_keeps")||amount(Objects.requireNonNullElse(order.get("tax_refund_amount"),BigDecimal.ZERO)).signum()!=0)throw blocked("AS_ESCROW_TAX_REQUIRES_RECONCILIATION");
  JsonNode agreed=object(order.get("agreed_json"));if(!IntentPricing.EXTERNAL_VERSION.equals(agreed.path("pricing_version").asText())||decimal(agreed,"insurance_escrow").signum()!=0)throw blocked("AS_ESCROW_PRICING_VERSION_UNPROVEN");
  Map<String,Object> reservation=one("SELECT * FROM t_product_order_reservations WHERE order_id=?"+suffix,orderId);if(!"consumed".equals(reservation.get("stock_state"))||!"CNY".equals(reservation.get("currency"))||!buyer.equals(reservation.get("buyer_id"))||!vendor.equals(reservation.get("vendor_id"))||!Objects.equals(order.get("trip_id"),reservation.get("trip_id"))||!Objects.equals(order.get("quantity"),reservation.get("quantity"))||!Objects.equals(agreed.path("product_id").asText(),reservation.get("product_id")))throw blocked("AS_ESCROW_PRODUCT_ATTRIBUTION_UNPROVEN");
  BigDecimal goods=amount(reservation.get("goods_amount")),fee=amount(reservation.get("service_fee")),unit=amount(reservation.get("unit_price"));if(goods.signum()<=0||goods.compareTo(amount(order.get("goods_amount")))!=0||fee.compareTo(amount(order.get("service_fee")))!=0||fee.compareTo(goods.multiply(new BigDecimal("0.05")).setScale(2,RoundingMode.HALF_UP))!=0||!(reservation.get("quantity") instanceof Number quantity)||quantity.intValue()<1||unit.multiply(BigDecimal.valueOf(quantity.longValue())).compareTo(goods)!=0)throw blocked("AS_ESCROW_PRICE_SNAPSHOT_MISMATCH");
  if(decimal(agreed,"unit_price").compareTo(unit)!=0)throw blocked("AS_ESCROW_UNIT_PRICE_MISMATCH");JsonNode original=object(reservation.get("snapshot"));if(!IntentPricing.EXTERNAL_VERSION.equals(original.path("pricing_version").asText())||decimal(original,"buyer_escrow").compareTo(goods.add(fee))!=0||decimal(original,"insurance_escrow").signum()!=0||!Objects.equals(original.path("product_id").asText(),reservation.get("product_id")))throw blocked("AS_ESCROW_ORIGINAL_FUNDING_UNPROVEN");
  BigDecimal shipping=agreed.hasNonNull("shipping_escrow")?amount(agreed.path("shipping_escrow").asText()):BigDecimal.ZERO.setScale(2);if(shipping.signum()<0||shipping.compareTo(new BigDecimal("2000"))>0)throw blocked("AS_ESCROW_SHIPPING_UNPROVEN");
  var executions=db.queryForList("SELECT * FROM t_order_escrow_refunds WHERE order_id=? ORDER BY created_at,id",orderId);BigDecimal refunded=BigDecimal.ZERO.setScale(2);var expectedLedgers=new HashMap<String,BigDecimal>();for(var execution:executions){if(!buyer.equals(execution.get("buyer_id"))||!"CNY".equals(execution.get("currency"))||truth(execution.get("requires_accounting")))throw blocked("AS_ESCROW_ACCOUNTING_REQUIRED");BigDecimal paid=amount(execution.get("amount"));if(paid.signum()<=0||amount(execution.get("original_goods_amount")).compareTo(goods)!=0||expectedLedgers.put(text(execution,"wallet_ledger_id"),paid)!=null)throw blocked("AS_ESCROW_REFUND_HISTORY_INVALID");refunded=refunded.add(paid);}if(refunded.compareTo(goods)>=0)throw blocked("AS_ESCROW_ACCOUNTING_REQUIRED");
  var deposits=db.queryForList("SELECT id,payer_id,party_role,kind,amount,status FROM t_deposits WHERE order_id=? ORDER BY id"+suffix,orderId);var buyerRows=deposits.stream().filter(r->"buyer".equals(r.get("party_role"))).toList();if(buyerRows.size()!=1)throw blocked("AS_ESCROW_BUYER_DEPOSIT_NOT_UNIQUE");var deposit=buyerRows.getFirst();BigDecimal held=goods.add(fee).add(shipping).subtract(refunded);if(!buyer.equals(deposit.get("payer_id"))||!"buyer_escrow".equals(deposit.get("kind"))||!"frozen".equals(deposit.get("status"))||held.compareTo(amount(deposit.get("amount")))!=0||held.compareTo(amount(order.get("buyer_deposit")))!=0||held.compareTo(decimal(agreed,"buyer_escrow"))!=0)throw blocked("AS_ESCROW_FROZEN_BALANCE_MISMATCH");if(agreed.hasNonNull("goods_refunded")&&decimal(agreed,"goods_refunded").compareTo(refunded)!=0)throw blocked("AS_ESCROW_REFUND_SNAPSHOT_MISMATCH");
  // Reconstruct the immutable refund chain by balances, not millisecond timestamps or random IDs.
  // Shipping may be appended between two refunds; compare each execution after removing its own shipping allocation.
  var chain=new HashMap<BigDecimal,Map<String,Object>>();for(var execution:executions){BigDecimal shipAt=amount(execution.get("shipping_held")),beforeAt=amount(execution.get("buyer_escrow_before")),afterAt=amount(execution.get("buyer_escrow_after"));if(!orderId.equals(execution.get("order_id"))||!Objects.equals(deposit.get("id"),execution.get("source_deposit_id"))||amount(execution.get("service_fee_held")).compareTo(fee)!=0||shipAt.signum()<0||shipAt.compareTo(shipping)>0||beforeAt.subtract(afterAt).compareTo(amount(execution.get("amount")))!=0||chain.put(beforeAt.subtract(shipAt),execution)!=null)throw blocked("AS_ESCROW_REFUND_CHAIN_INVALID");}
  BigDecimal chainBalance=goods.add(fee);for(int i=0;i<executions.size();i++){var execution=chain.remove(chainBalance);if(execution==null)throw blocked("AS_ESCROW_REFUND_CHAIN_INVALID");chainBalance=amount(execution.get("buyer_escrow_after")).subtract(amount(execution.get("shipping_held")));}if(!chain.isEmpty()||chainBalance.compareTo(goods.add(fee).subtract(refunded))!=0)throw blocked("AS_ESCROW_REFUND_CHAIN_INVALID");
  var ledgers=db.queryForList("SELECT id,user_id,kind,amount FROM t_balance_ledger WHERE order_id=? ORDER BY created_at,id",orderId);int initialCount=0;BigDecimal shippingDebit=BigDecimal.ZERO.setScale(2);for(var ledger:ledgers){BigDecimal delta=amount(ledger.get("amount"));String kind=text(ledger,"kind");if("goods_settlement".equals(kind))throw blocked("AS_ESCROW_GOODS_ALREADY_PAID");if(!buyer.equals(ledger.get("user_id"))){if(delta.signum()>0)throw blocked("AS_ESCROW_OTHER_PARTY_ALREADY_PAID");continue;}if("deposit_freeze".equals(kind)&&delta.signum()<0){initialCount++;if(delta.negate().compareTo(goods.add(fee))!=0)throw blocked("AS_ESCROW_INITIAL_DEBIT_MISMATCH");}else if("shipping_freeze".equals(kind)&&delta.signum()<0)shippingDebit=shippingDebit.add(delta.negate());else if(LEDGER_KIND.equals(kind)&&delta.signum()>0){BigDecimal expected=expectedLedgers.remove(text(ledger,"id"));if(expected==null||expected.compareTo(delta)!=0)throw blocked("AS_ESCROW_REFUND_LEDGER_MISMATCH");}else if(delta.signum()!=0)throw blocked("AS_ESCROW_OTHER_WALLET_MOVEMENT");}if(initialCount!=1||shippingDebit.compareTo(shipping)!=0||!expectedLedgers.isEmpty())throw blocked("AS_ESCROW_FUNDING_LEDGER_UNPROVEN");
  if(!db.queryForList("SELECT id FROM t_reward_ledger WHERE order_id=? AND status<>'revoked' ORDER BY id",orderId).isEmpty())throw blocked("AS_ESCROW_REWARDS_REQUIRE_RECONCILIATION");return new Proof(order,reservation,deposit,executions,goods,fee,shipping,refunded,held,buyer,vendor);
 }
}
